// PARSEAR TWITTER - Valida e extrai JSON do agent
const input = $('EXTRAIR DADOS POST').first().json;
const raw = $input.first().json.output;

function parseJSON(str) {
  if (!str) return null;
  let s = String(str).replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const match = s.match(/\{[\s\S]*\}/);
  if (match) s = match[0];
  s = s.replace(/,\s*#/g, ', "#').replace(/\[\s*#/g, '["#').replace(/#([\w]+)([,\]])/g, '"#$1"$2');
  try { return JSON.parse(s); } catch (e) { return null; }
}

const twitter = parseJSON(raw);
if (!twitter || !twitter.tweet1_hook) {
  throw new Error('Twitter: JSON invalido ou incompleto');
}

return {
  json: {
    ...input,
    twitter: twitter
  }
};

// PARSEAR LINKEDIN - Valida e extrai JSON do agent
// Busca dados acumulados do PARSEAR TWITTER (nao do $input que e so output do agent)
