// PREPARAR PREVIEW - Combina dados do Merge
const allItems = $input.all();

let socialData = null;
let imageData = null;

for (const item of allItems) {
  if (item.json.twitter && item.json.linkedin && item.json.instagram) {
    socialData = item.json;
  }
  if (item.json.twitter_image_url) {
    imageData = item.json;
  }
}

if (!socialData) {
  socialData = $('PARSEAR INSTAGRAM').first().json;
}

const sessionId = $execution.id;
const chatId = '8375309778';

const truncate = (text, max) => text && text.length > max ? text.substring(0, max-3) + '...' : (text || '');

const twitterImageUrl = imageData ? imageData.twitter_image_url : null;

// Caption da imagem (curta)
const imageCaption = `🖼 *IMAGEM TWITTER*\n\n📰 ${truncate(socialData.title, 60)}\n\n_Aprove a imagem ou solicite uma nova._`;

// Botoes da imagem
const imageReplyMarkup = {
  inline_keyboard: [
    [{ text: '✅ Aprovar Imagem', callback_data: `img_approve_${sessionId}` }],
    [{ text: '🔄 Refazer Imagem', callback_data: `img_redo_${sessionId}` }],
    [{ text: '❌ Cancelar Tudo', callback_data: `img_cancel_${sessionId}` }]
  ]
};

// Preview completo do conteudo (texto)
const preview = `📱 *PREVIEW REDES SOCIAIS*\n━━━━━━━━━━━━━━━━━━━━━\n\n📰 *Post:* ${truncate(socialData.title, 80)}\n🔗 ${socialData.wordpress_url}\n\n━━━━━━━━━━━━━━━━━━━━━\n🐦 *TWITTER/X (Thread 4 tweets):*\n\n1️⃣ ${socialData.twitter.tweet1_hook}\n\n2️⃣ ${socialData.twitter.tweet2_contexto}\n\n3️⃣ ${socialData.twitter.tweet3_brasil}\n\n4️⃣ ${socialData.twitter.tweet4_cta}\n\n━━━━━━━━━━━━━━━━━━━━━\n💼 *LINKEDIN:*\n\n${truncate(socialData.linkedin.post, 800)}\n\n━━━━━━━━━━━━━━━━━━━━━\n📸 *INSTAGRAM:*\n\n${truncate(socialData.instagram.caption, 600)}\n\n━━━━━━━━━━━━━━━━━━━━━`;

// Botoes do conteudo (aparecem depois de aprovar imagem)
const contentReplyMarkup = {
  inline_keyboard: [
    [{ text: '✅ PUBLICAR TODAS', callback_data: `social_all_${sessionId}` }],
    [{ text: '🐦 Só Twitter', callback_data: `social_twitter_${sessionId}` }, { text: '💼 Só LinkedIn', callback_data: `social_linkedin_${sessionId}` }],
    [{ text: '📸 Só Instagram', callback_data: `social_instagram_${sessionId}` }, { text: '❌ Cancelar', callback_data: `social_cancel_${sessionId}` }]
  ]
};

return {
  json: {
    chat_id: chatId,
    // Dados da imagem
    twitter_image_url: twitterImageUrl,
    image_caption: imageCaption,
    image_reply_markup: imageReplyMarkup,
    // Dados do preview texto
    text: preview,
    parse_mode: 'Markdown',
    reply_markup: contentReplyMarkup,
    // Dados gerais
    post_id: socialData.post_id,
    title: socialData.title,
    wordpress_url: socialData.wordpress_url,
    social_content: {
      twitter: socialData.twitter,
      linkedin: socialData.linkedin,
      instagram: socialData.instagram
    },
    session_id: sessionId
  }
};

// PREPARAR GEMINI TWITTER
const inputData = $('EXTRAIR DADOS POST').first().json;
const aiResponse = $json;

const imagePrompt = aiResponse.text || aiResponse.output || aiResponse.response || '';

const timestamp = Date.now();
const sanitizedTitle = inputData.title.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').substring(0, 40);

const imageFilename = `twitter-${sanitizedTitle}-${timestamp}.png`;
const storagePath = `twitter/${inputData.post_id}/${imageFilename}`;

return { json: { post_id: inputData.post_id, title: inputData.title, twitter_image_prompt: imagePrompt, twitter_image_filename: imageFilename, twitter_storage_path: storagePath } };

// CONSTRUIR URL TWITTER
const prevData = $('PREPARAR GEMINI TWITTER').first().json;
const storagePath = prevData.twitter_storage_path;

const twitterImageUrl = `https://pbhvhfahcvgmgjvuhwuk.supabase.co/storage/v1/object/public/social-images/${storagePath}`;

return { json: { post_id: prevData.post_id, title: prevData.title, twitter_image_url: twitterImageUrl, twitter_image_prompt: prevData.twitter_image_prompt } };

